// Which Python Hub samples can actually execute in the browser.
//
// Generated by executing all 126 samples in Pyodide (see BUILD notes in
// MASTER_PRD §8/#11). 110 run; the entries below cannot, each for a reason
// that is a property of the browser runtime rather than a flaw in the code —
// so the UI states the reason instead of hiding the button or, worse,
// offering a Run that always fails.
//
// Regenerate after adding or editing a sample; the accompanying test asserts
// every id here still exists.
export const NOT_RUNNABLE = {
  mu_xbar: { kind: "slow", why: "runs too long for a browser tab (large simulation)" },
  naive_bayes: { kind: "network", why: "downloads a dataset at runtime, which the sandboxed runtime cannot do" },
  rf: { kind: "network", why: "downloads a dataset at runtime, which the sandboxed runtime cannot do" },
  xgboost: { kind: "package", why: "xgboost is not available in the browser runtime" },
  lightgbm: { kind: "package", why: "lightgbm is not available in the browser runtime" },
  catboost: { kind: "package", why: "catboost is not available in the browser runtime" },
  stacking: { kind: "slow", why: "runs too long for a browser tab (large simulation)" },
  svm: { kind: "heavy", why: "exhausts the tab's memory (grid search over a large kernel)" },
  garch: { kind: "package", why: "arch is not available in the browser runtime" },
  prophet: { kind: "package", why: "Prophet is not available in the browser runtime" },
  rnn: { kind: "package", why: "PyTorch is not available in the browser runtime" },
  lstm: { kind: "package", why: "PyTorch is not available in the browser runtime" },
  cnn: { kind: "package", why: "PyTorch is not available in the browser runtime" },
  transformer: { kind: "package", why: "PyTorch is not available in the browser runtime" },
  bstsbnn: { kind: "package", why: "PyTorch is not available in the browser runtime" },
  actorcritic: { kind: "package", why: "PyTorch and Gymnasium are not available in the browser runtime" },
};

/** Runtime constraints worth surfacing next to the Run button. */
export const RUNTIME_NOTE = 'First run downloads the Python runtime (~10 MB) into your browser. Nothing is uploaded; the code executes locally.';

export function runnability(id) {
  const blocked = NOT_RUNNABLE[id];
  return blocked ? { runnable: false, ...blocked } : { runnable: true };
}
